USE [JamunaBankProcurement];
GO
CREATE OR ALTER PROCEDURE dbo.usp_WorkOrder_CreateAndAssign @WorkOrderNo VARCHAR(60),@WorkOrderDate DATE,@SupplierVendor NVARCHAR(300),@ContractAgreementNo VARCHAR(100)=NULL,@WorkOrderValue DECIMAL(18,2),@DeliveryDate DATE=NULL,@Remarks NVARCHAR(2000)=NULL,@Requisitions dbo.WorkOrderRequisitionTableType READONLY,@ActorEmployeeId VARCHAR(30)
AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;BEGIN TRY BEGIN TRAN;IF NOT EXISTS(SELECT 1 FROM @Requisitions)THROW 51000,'At least one requisition is required.',1;IF NULLIF(LTRIM(RTRIM(@WorkOrderNo)),'')IS NULL OR NULLIF(LTRIM(RTRIM(@SupplierVendor)),'')IS NULL OR @WorkOrderDate IS NULL OR @WorkOrderValue<0 OR(@DeliveryDate IS NOT NULL AND @DeliveryDate<@WorkOrderDate)THROW 51000,'Work Order header values are invalid.',1;DECLARE @sid BIGINT=(SELECT STATUS_ID FROM dbo.PROCUREMENT_STATUS_MASTER WHERE STATUS_CODE='WORK_ORDER_ISSUED'AND IS_ACTIVE=1);IF @sid IS NULL THROW 51000,'WORK_ORDER_ISSUED status is not configured.',1;IF EXISTS(SELECT 1 FROM @Requisitions x LEFT JOIN dbo.REQUISITION_HEADER h ON h.REQUISITION_ID=x.REQUISITION_ID LEFT JOIN dbo.PROCUREMENT_TRACKING p ON p.REQUISITION_ID=x.REQUISITION_ID LEFT JOIN dbo.PROCUREMENT_STATUS_MASTER s ON s.STATUS_ID=p.CURRENT_STATUS_ID WHERE h.REQUISITION_ID IS NULL OR h.IS_ACTIVE=0 OR p.PROCUREMENT_ID IS NULL OR s.STATUS_CODE NOT IN('READY_FOR_PROCUREMENT','READY_FOR_WORK_ORDER'))THROW 51000,'Every selected requisition must be ready for procurement or ready for Work Order.',1;IF EXISTS(SELECT 1 FROM @Requisitions x JOIN dbo.WORK_ORDER_REQUISITION wr ON wr.REQUISITION_ID=x.REQUISITION_ID)THROW 51000,'A selected requisition is already assigned to a Work Order.',1;INSERT dbo.WORK_ORDER_HEADER(WORK_ORDER_NO,WORK_ORDER_DATE,SUPPLIER_VENDOR,CONTRACT_AGREEMENT_NO,WORK_ORDER_VALUE,DELIVERY_DATE,REMARKS,CREATED_BY)VALUES(LTRIM(RTRIM(@WorkOrderNo)),@WorkOrderDate,LTRIM(RTRIM(@SupplierVendor)),NULLIF(LTRIM(RTRIM(@ContractAgreementNo)),''),@WorkOrderValue,@DeliveryDate,@Remarks,@ActorEmployeeId);DECLARE @id BIGINT=SCOPE_IDENTITY();INSERT dbo.WORK_ORDER_REQUISITION(WORK_ORDER_ID,REQUISITION_ID,ALLOCATED_AMOUNT,REMARKS)SELECT @id,REQUISITION_ID,ALLOCATED_AMOUNT,REMARKS FROM @Requisitions;UPDATE p SET CURRENT_STATUS_ID=@sid,PROCUREMENT_REFERENCE_NO=@WorkOrderNo,MODIFIED_DATE=SYSUTCDATETIME()FROM dbo.PROCUREMENT_TRACKING p JOIN @Requisitions x ON x.REQUISITION_ID=p.REQUISITION_ID;INSERT dbo.PROCUREMENT_STATUS_HISTORY(PROCUREMENT_ID,STATUS_ID,STATUS_DATE,REFERENCE_NO,CHANGED_BY_EMPLOYEE_ID,REMARKS)SELECT p.PROCUREMENT_ID,@sid,SYSUTCDATETIME(),@WorkOrderNo,@ActorEmployeeId,@Remarks FROM dbo.PROCUREMENT_TRACKING p JOIN @Requisitions x ON x.REQUISITION_ID=p.REQUISITION_ID;UPDATE h SET CURRENT_STATUS='PROCUREMENT_IN_PROGRESS',MODIFIED_BY=@ActorEmployeeId,MODIFIED_DATE=SYSUTCDATETIME()FROM dbo.REQUISITION_HEADER h JOIN @Requisitions x ON x.REQUISITION_ID=h.REQUISITION_ID;INSERT dbo.AUDIT_LOG(ENTITY_NAME,ENTITY_ID,ACTION_TYPE,NEW_VALUE_JSON,ACTION_BY_EMPLOYEE_ID)SELECT'WORK_ORDER_HEADER',@id,'CREATE',(SELECT @WorkOrderNo WorkOrderNo,@WorkOrderDate WorkOrderDate,@SupplierVendor SupplierVendor,@WorkOrderValue WorkOrderValue FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),@ActorEmployeeId;INSERT dbo.AUDIT_LOG(ENTITY_NAME,ENTITY_ID,ACTION_TYPE,NEW_VALUE_JSON,ACTION_BY_EMPLOYEE_ID)SELECT'WORK_ORDER_REQUISITION',x.REQUISITION_ID,'ASSIGN',(SELECT @id WorkOrderId,x.REQUISITION_ID RequisitionId FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),@ActorEmployeeId FROM @Requisitions x;COMMIT;SELECT'000'RESULT_CODE,N'Success'RESULT_MESSAGE,@id ENTITY_ID,@WorkOrderNo REFERENCE_NO;END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK;SELECT CASE ERROR_NUMBER()WHEN 51000 THEN'001'WHEN 2601 THEN'005'WHEN 2627 THEN'005'ELSE'999'END RESULT_CODE,ERROR_MESSAGE()RESULT_MESSAGE,NULL ENTITY_ID,@WorkOrderNo REFERENCE_NO;END CATCH END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_WorkOrder_GetById @WorkOrderId BIGINT
AS BEGIN SET NOCOUNT ON;SELECT WORK_ORDER_ID,WORK_ORDER_NO,WORK_ORDER_DATE,SUPPLIER_VENDOR,CONTRACT_AGREEMENT_NO,WORK_ORDER_VALUE,DELIVERY_DATE,REMARKS FROM dbo.WORK_ORDER_HEADER WHERE WORK_ORDER_ID=@WorkOrderId;SELECT wr.WORK_ORDER_ID,h.REQUISITION_ID,h.REQUISITION_NO,h.TOTAL_ESTIMATED_AMOUNT,s.STATUS_CODE FROM dbo.WORK_ORDER_REQUISITION wr JOIN dbo.REQUISITION_HEADER h ON h.REQUISITION_ID=wr.REQUISITION_ID JOIN dbo.PROCUREMENT_TRACKING p ON p.REQUISITION_ID=h.REQUISITION_ID JOIN dbo.PROCUREMENT_STATUS_MASTER s ON s.STATUS_ID=p.CURRENT_STATUS_ID WHERE wr.WORK_ORDER_ID=@WorkOrderId ORDER BY h.REQUISITION_NO;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_WorkOrder_GetByRequisition @RequisitionId BIGINT
AS BEGIN SET NOCOUNT ON;SELECT w.WORK_ORDER_ID,w.WORK_ORDER_NO,w.WORK_ORDER_DATE,w.SUPPLIER_VENDOR,w.CONTRACT_AGREEMENT_NO,w.WORK_ORDER_VALUE,w.DELIVERY_DATE,w.REMARKS FROM dbo.WORK_ORDER_REQUISITION x JOIN dbo.WORK_ORDER_HEADER w ON w.WORK_ORDER_ID=x.WORK_ORDER_ID WHERE x.REQUISITION_ID=@RequisitionId ORDER BY w.WORK_ORDER_DATE DESC;SELECT wr.WORK_ORDER_ID,h.REQUISITION_ID,h.REQUISITION_NO,h.TOTAL_ESTIMATED_AMOUNT,s.STATUS_CODE FROM dbo.WORK_ORDER_REQUISITION wr JOIN dbo.REQUISITION_HEADER h ON h.REQUISITION_ID=wr.REQUISITION_ID JOIN dbo.PROCUREMENT_TRACKING p ON p.REQUISITION_ID=h.REQUISITION_ID JOIN dbo.PROCUREMENT_STATUS_MASTER s ON s.STATUS_ID=p.CURRENT_STATUS_ID WHERE wr.WORK_ORDER_ID IN(SELECT WORK_ORDER_ID FROM dbo.WORK_ORDER_REQUISITION WHERE REQUISITION_ID=@RequisitionId)ORDER BY wr.WORK_ORDER_ID,h.REQUISITION_NO;END;
GO
